package com.bananalab.lite;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import android.text.util.Linkify;import org.json.*;import java.io.*;import java.util.*;
/** Single user workspace: conversation, inline visual results, editing and export. */
public final class BananaActivity extends Activity implements BananaSceneCard.Host{
 private LinearLayout messages,root;private Button projectNav;private ScrollView scroll;private EditText input;private Button send,tools;private TextView status;private JSONArray history;private String topic="";private Thread worker;private volatile boolean dead,cancelExport;private boolean busy,exporting,resumed;private BananaSceneCard active;private LinearLayout activeHolder;private JSONObject activeRow;private JSONObject exportRequest,importRequest;private long renderGeneration,chatRunId;
 private String codeExportPath="";
 private void codeAction(String mode){Intent pick=new Intent(mode.startsWith("code_import")?Intent.ACTION_OPEN_DOCUMENT:Intent.ACTION_CREATE_DOCUMENT);pick.addCategory(Intent.CATEGORY_OPENABLE);pick.setType(mode.equals("code_export_apk")?"application/vnd.android.package-archive":mode.endsWith("backup")?"application/json":"application/zip");if(mode.startsWith("code_export")){codeExportPath=DurableCode.prefs(this).getString("export","");pick.putExtra(Intent.EXTRA_TITLE,mode.equals("code_export_apk")?"Banana.apk":"Banana-codigo.json");}startActivityForResult(pick,mode.equals("code_import_key")?40:mode.startsWith("code_export")?41:42);}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextColor(Color.WHITE);t.setTextSize(size);t.setPadding(dp(10),dp(7),dp(10),dp(7));return t;}
 @Override public void onCreate(Bundle state){super.onCreate(state);try{getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);getWindow().setStatusBarColor(0xff141922);getWindow().setNavigationBarColor(0xff141922);WebMemory.restore(this);VisualMemory.restore(this);
  root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(ModularHub.background());root.setPadding(dp(10),dp(8),dp(10),dp(8));setContentView(root);root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(dp(10),dp(8)+insets.getSystemWindowInsetTop(),dp(10),dp(8)+insets.getSystemWindowInsetBottom());return insets;});
  LinearLayout header=new LinearLayout(this);TextView title=text("BANANA",25);title.setTextColor(0xfff6cf66);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));tools=new Button(this);tools.setText("Proyecto");tools.setAllCaps(false);header.addView(tools);projectNav=new Button(this);projectNav.setText("Proyectos");projectNav.setAllCaps(false);projectNav.setOnClickListener(v->{if(!locked())projectDashboard();});header.addView(projectNav);root.addView(header);root.addView(text("Conversá, diseñá y animá en el mismo lugar",12));tools.setOnClickListener(v->menu());
  scroll=new ScrollView(this);messages=new LinearLayout(this);messages.setOrientation(1);scroll.addView(messages);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));status=text("Listo",12);root.addView(status);LinearLayout composer=new LinearLayout(this);input=new EditText(this);input.setTextColor(Color.WHITE);input.setHintTextColor(0xffb7c3cf);input.setHint("Preguntá, investigá o contá qué querés crear…");input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);input.setMaxLines(3);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(KnowledgeNotebook.TEXT+64)});composer.addView(input,new LinearLayout.LayoutParams(0,-2,1));send=new Button(this);send.setText("Enviar");send.setAllCaps(false);composer.addView(send);root.addView(composer);send.setOnClickListener(v->submit());history=BananaConversation.load(this);topic=BananaConversation.topic(this);
  if(state!=null){input.setText(state.getString("draft",""));String q=state.getString("export",""),ref=state.getString("import","");if(!q.isEmpty())exportRequest=new JSONObject(q);if(!ref.isEmpty())importRequest=new JSONObject(ref);}
  if(history.length()==0)record("Banana","Soy Banana. Pedime un personaje o una escena y vas a ver el resultado acá. Mi conversación libre todavía es experimental.",null,false,false);
  SceneDraft current=BananaProject.current(this);if(current!=null){boolean found=false;for(int i=history.length()-1;i>=0;i--){SceneDraft snap=BananaConversation.snapshot(history.getJSONObject(i));if(snap!=null){found=BananaProject.same(snap,current)&&history.getJSONObject(i).optBoolean("draft")==BananaProject.isDraft(this);break;}}if(!found)record("Banana","Tu proyecto está listo para continuar.",current,BananaProject.isDraft(this),false);}
  refreshAppStyle();showHistory(false);if(getIntent().getBooleanExtra("open_editor",false)){final String id=getIntent().getStringExtra("actor");new Handler().post(()->{if(active!=null)active.edit(id);if(getIntent().getBooleanExtra("import_reference",false)&&active!=null)importReference(active.snapshot,id==null?active.snapshot.focused:id,false);});}
 }catch(Exception e){Diagnostics.show(this,e);}}
 private void record(String who,String value,SceneDraft snapshot,boolean draft,boolean redraw){try{history=BananaConversation.append(history,who,value,snapshot,draft);BananaConversation.save(this,history,topic);if(redraw)showHistory(snapshot!=null&&!draft);}catch(Exception e){failed(e.getMessage());}}
 private void showHistory(boolean auto){renderGeneration++;if(active!=null)active.close();active=null;activeHolder=null;activeRow=null;messages.removeAllViews();LinearLayout lastHolder=null;JSONObject lastRow=null;
  for(int i=0;i<history.length();i++){JSONObject row=history.optJSONObject(i);if(row==null)continue;TextView bubble=text(row.optString("who")+"\n"+row.optString("text"),ModularHub.view().text);bubble.setTextIsSelectable(true);bubble.setBackgroundColor(row.optString("who").equals("Vos")?0xff344554:0xff202c38);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(ModularHub.view().spacing/2),0,dp(ModularHub.view().spacing/2));messages.addView(bubble,p);Linkify.addLinks(bubble,Linkify.WEB_URLS);if(row.has("scene")){LinearLayout holder=new LinearLayout(this);holder.setOrientation(1);messages.addView(holder);placeholder(holder,row);lastHolder=holder;lastRow=row;}}
  if(lastHolder!=null)mount(lastHolder,lastRow,auto);buttonStyles(root);scroll.post(()->scroll.fullScroll(View.FOCUS_DOWN));
 }
 private void placeholder(LinearLayout holder,JSONObject row){holder.removeAllViews();Button b=new Button(this);b.setText(row.optBoolean("draft")?"Ver borrador de este mensaje":"Ver resultado de este mensaje");b.setAllCaps(false);holder.addView(b);b.setOnClickListener(v->{if(!locked())mount(holder,row,false);});}
 private void mount(LinearLayout holder,JSONObject row,boolean auto){try{if(active!=null){active.close();if(activeHolder!=holder)placeholder(activeHolder,activeRow);}holder.removeAllViews();BananaSceneCard card=new BananaSceneCard(this,BananaConversation.snapshot(row),row.optBoolean("draft"),this);active=card;activeHolder=holder;activeRow=row;holder.addView(card);card.setForeground(resumed);card.prepare(auto&&resumed&&SceneTiming.seconds(card.snapshot)<=12);}catch(Exception e){failed(e.getMessage());}}
 @Override public void activate(BananaSceneCard card){if(active!=null&&active!=card)active.stop();}
 @Override public boolean locked(){return busy||exporting||dead;}
 private void lock(boolean value){busy=value;LearningLoop.setBusy(value);send.setEnabled(!value&&!exporting);tools.setEnabled(!value&&!exporting);}
 private void watchCompiler(final long id){new android.os.Handler(android.os.Looper.getMainLooper()).postDelayed(()->{if(!dead&&busy&&chatRunId==id&&worker!=null&&worker.isAlive()){if(!JavaChat.progress.isEmpty())status.setText(JavaChat.progress);watchCompiler(id);}},350);}
 private void submit(){if(locked())return;String message=input.getText().toString().trim();if(message.isEmpty())return;if(message.length()>8000&&!GeneralSourceChat.sourceMessage(message)&&!KnowledgeNotebook.teachingMessage(message)&&!message.matches("(?is)^(?:edita metodo java|escribe archivo java|reescribe el metodo del chat|repara metodo del chat|diagnostica metodo del chat) .*")){failed("Para conversar podés usar hasta8000 caracteres. Los textos de aprendizaje admiten hasta262144; las fuentes Java mantienen sus límites.");return;}input.setText("");InputMethodManager keyboard=(InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);if(keyboard!=null)keyboard.hideSoftInputFromWindow(input.getWindowToken(),0);input.clearFocus();if(active!=null)active.stop();record("Vos",message.length()>8000?message.substring(0,8000)+"\n[Texto largo guardado en el cuaderno; vista del historial abreviada.]":message,null,false,false);showHistory(false);lock(true);status.setText("Banana está preparando la respuesta…");final List<String[]> turns;try{turns=BananaConversation.context(history);}catch(Exception e){lock(false);failed(e.getMessage());return;}worker=new Thread(()->{try{BananaEngine.Result result=BananaEngine.run(getApplicationContext(),message,turns,topic,getSharedPreferences("banana-chat",0).getBoolean("transformer",true),null);if(result==null||result.text==null||result.text.trim().isEmpty())throw new IllegalStateException("El motor no devolvió una respuesta; el pedido no se confirmó");if(!dead)runOnUiThread(()->{lock(false);topic=result.topic;boolean visual=result.scene!=null&&(result.changed||result.mode.equals("escena")||result.mode.equals("borrador")||!result.studioId.isEmpty());refreshAppStyle();record("Banana",result.text,visual?result.scene:null,result.draft,true);status.setText(result.mode.equals("transformer")?"Texto experimental; puede equivocarse.":result.draft?"Borrador guardado · falta publicar":"Listo");if(result.mode.startsWith("code_"))codeAction(result.mode);if(result.mode.startsWith("knowledge_"))knowledgeAction(result.mode);if(result.mode.equals("modular_panels"))modularPanels();if(result.mode.equals("app_proyectos"))projectDashboard();if(!result.studioId.isEmpty()&&active!=null)active.edit(result.studioId);if(result.importReference&&result.scene!=null)importReference(result.scene,result.studioId,false);});}catch(Throwable e){if(!dead)runOnUiThread(()->{lock(false);record("Banana","No pude completar el pedido: "+AndroidRepair.summary(e),null,false,true);});}},"banana-unified-engine");worker.start();watchCompiler(++chatRunId);}
 private void refreshAppStyle(){root.setBackgroundColor(ModularHub.background());getWindow().setStatusBarColor(ModularHub.background());getWindow().setNavigationBarColor(ModularHub.background());input.setTextSize(ModularHub.view().text);projectNav.setVisibility(ModularHub.view().projects?View.VISIBLE:View.GONE);buttonStyles(root);}
 private final java.util.WeakHashMap<Button,android.content.res.ColorStateList[]> originalButtonColors=new java.util.WeakHashMap<>();
 private void buttonStyles(View view){UiTypeface.apply(view);if(view instanceof Button){Button b=(Button)view;if(!originalButtonColors.containsKey(b))originalButtonColors.put(b,new android.content.res.ColorStateList[]{b.getBackgroundTintList(),b.getTextColors()});b.setTextSize(ModularHub.view().buttons);int accent=AppJavaWorkspace.buttonColor(ModularHub.view(),b.getText().toString());if(accent>0){b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(new int[]{0,0xff174c80,0xff205333,0xff603080,0xff962a32,0xff684e00}[accent]));b.setTextColor(0xffffffff);}else{android.content.res.ColorStateList[] original=originalButtonColors.get(b);b.setBackgroundTintList(original[0]);b.setTextColor(original[1]);}}if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)buttonStyles(group.getChildAt(i));}}
 private void projectDashboard(){if(locked())return;UiTypeface.show(new AlertDialog.Builder(this).setTitle("Proyectos de Banana").setItems(new String[]{"Escenas guardadas: abrir / guardar","Personajes guardados","Escena actual","Borrador actual","Versiones de la app"},(d,i)->{if(i==0)CreationPanels.scenes(this,()->edited("Abrí la escena guardada.",""));else command(new String[]{"","mis personajes","mostrame el plan","ver borrador","versiones de la app"}[i]);}).setNegativeButton("Volver al chat",null));}
 private void modularPanels(){if(locked())return;ModularHub.Bundle b=ModularHub.active;if(b==null||b.panels.length()==0){command("como cambio banana sin reinstalar");return;}try{String[] names=new String[b.panels.length()];for(int i=0;i<names.length;i++)names[i]=b.panels.getJSONObject(i).getString("name");UiTypeface.show(new AlertDialog.Builder(this).setTitle("Herramientas modulares").setItems(names,(d,index)->{try{JSONArray buttons=b.panels.getJSONObject(index).getJSONArray("buttons");String[] labels=new String[buttons.length()];for(int j=0;j<labels.length;j++)labels[j]=buttons.getJSONObject(j).getString("label");UiTypeface.show(new AlertDialog.Builder(this).setTitle(names[index]).setItems(labels,(dialog,at)->{try{command(buttons.getJSONObject(at).getString("command"));}catch(Exception e){failed(e.getMessage());}}).setNegativeButton("Volver",null));}catch(Exception e){failed(e.getMessage());}}).setNegativeButton("Cerrar",null));}catch(Exception e){failed(e.getMessage());}}
 private void command(String message){if(locked())return;input.setText(message);submit();}
 private void learningPanel(){try{boolean on=LearningLoop.enabled(this);UiTypeface.show(new AlertDialog.Builder(this).setTitle("Aprendizaje continuo").setMessage(LearningLoop.summary(this)).setPositiveButton(on?"Pausar":"Reanudar",(d,w)->{try{if(on)LearningLoop.pause(this);else LearningLoop.enable(this);learningPanel();}catch(Exception e){failed(AndroidRepair.summary(e));}}).setNeutralButton("Ejercicios",(d,w)->{try{org.json.JSONArray rows=LearningLoop.portable(this).getJSONArray("history");StringBuilder text=new StringBuilder();for(int at=Math.max(0,rows.length()-3);at<rows.length();at++){JSONObject row=rows.getJSONObject(at);text.append("Pregunta: ").append(row.getString("evalQuestion")).append("\nIntento propio: ").append(row.getString("attempt")).append("\nRespuesta de la fuente: ").append(row.getString("answer")).append("\nCoincidencia exacta: ").append(row.getBoolean("correctExact")).append("\nFuente: ").append(row.getString("source")).append("\n\n");}if(text.length()==0)text.append("Todavía no hay ejercicios evaluados. Agregá una fuente y dejá continuar el aprendizaje.");UiTypeface.show(new AlertDialog.Builder(this).setTitle("Ejercicios de las fuentes").setMessage(text.toString()).setPositiveButton("Volver",(x,y)->learningPanel()));}catch(Exception e){failed(AndroidRepair.summary(e));}}).setNegativeButton("Cerrar",null));}catch(Exception e){failed(AndroidRepair.summary(e));}}
 private void menu(){if(locked())return;UiTypeface.show(new AlertDialog.Builder(this).setTitle("Tu proyecto en Banana").setItems(new String[]{"Ver plan actual","Ver borrador","Publicar borrador","Descartar borrador","Mis personajes","Mis escenas","Abrir / guardar escenas","Guardar serie MP4","Recuerdos del proyecto","Internet y aprendizaje","Imágenes de referencia","Deshacer","Rehacer","Opciones","Borrar conversación","Fuentes disponibles","Núcleo móvil","Taller de módulos","Java local","Mejorar hablando","Función de salto","Editor de métodos Java","Banana modular","Mis herramientas modulares","Aprendizaje local","Programador Android","Especialista Java y proyecto","Activar Java del proyecto","Código permanente y APK","Aprendizaje del planificador","Núcleo programador","Aprendizaje continuo"},(d,i)->{switch(i){case 31:learningPanel();break;case 0:command("mostrame el plan");break;case 1:command("ver borrador");break;case 2:command("publica el borrador");break;case 3:command("descarta el borrador");break;case 4:command("mis personajes");break;case 5:command("mis escenas");break;case 6:CreationPanels.scenes(this,()->edited("Abrí la escena guardada.",""));break;case 7:export("series",null);break;case 8:command("mis recuerdos");break;case 9:researchSettings();break;case 10:VisualMemory.show(this);break;case 11:command("deshacer");break;case 12:command("rehacer");break;case 13:options();break;case 14:clear();break;case 22:command("como cambio banana sin reinstalar");break;case 23:modularPanels();break;case 30:command("nucleo programador");break;case 28:command("codigo permanente");break;case 29:command("estado aprendizaje planificador");break;case 27:command("sustituciones java");break;case 26:command("especialista java android");break;case 25:command("programador android");break;case 24:command("estado del aprendizaje");break;case 21:command("como edito un metodo java");break;case 20:command("como cambio la funcion del salto");break;case 19:command("como puedo ajustar la app hablando");break;case 18:JavaWorkshop.show(this,t->command(t));break;case 17:RuntimeWorkshop.show(this,t->command(t));break;case 16:corePanel();break;case 15:UiTypeface.show(new AlertDialog.Builder(this).setTitle("Fuentes disponibles").setMessage(BananaReferences.SOURCES).setPositiveButton("Cerrar",null));break;}}).setNegativeButton("Cerrar",null));}
 private void corePanel(){UiTypeface.show(new AlertDialog.Builder(this).setTitle("Núcleo móvil · sin PC").setItems(new String[]{"Estado del núcleo","Explicar último resultado","Ver mi plan","Mis frases enseñadas","Mis correcciones","Explicaciones breves","Explicaciones detalladas","Lecciones sin conexión","Cómo preparar un plan"},(d,i)->{String[] commands={"estado del nucleo","que entendiste","ver mi plan","mis frases","mis correcciones","modo breve","modo detallado"};if(i<commands.length)command(commands[i]);else if(i==7)UiTypeface.show(new AlertDialog.Builder(this).setTitle("24 temas locales").setMessage("Programación, ciencia básica, dibujo, animación, guion, IA y matemática introductoria. Probá: qué es un algoritmo; dame un ejemplo; explicalo paso a paso. Son lecciones propias con selector neuronal; no un modelo que sabe todo.").setPositiveButton("Cerrar",null));else UiTypeface.show(new AlertDialog.Builder(this).setTitle("Planes corregibles").setMessage("planea: crea a Tony una banana; agrega un pepino llamado Milo; Tony baila\nDespués: aplica el plan.\nPara cambiarlo: corrige paso 2: agrega un tomate llamado Nora\nPara enseñar una frase: cuando diga \"fiesta\" quiero decir \"continua con Tony baila\"").setPositiveButton("Cerrar",null));}).setNegativeButton("Cerrar",null));}
 private void researchSettings(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(16),dp(8),dp(16),dp(8));TextView info=text(ResearchStore.status(this),13);info.setTextColor(Color.BLACK);box.addView(info);CheckBox enabled=new CheckBox(this);enabled.setText("Actualizar temas en segundo plano");enabled.setChecked(ResearchStore.prefs(this).getBoolean("enabled",true));box.addView(enabled);CheckBox wifi=new CheckBox(this);wifi.setText("Solo redes sin medición (normalmente Wi-Fi)");wifi.setChecked(ResearchStore.prefs(this).getBoolean("wifi",true));box.addView(wifi);CheckBox follow=new CheckBox(this);follow.setText("Seguir mis preguntas nuevas (hasta ocho temas)");follow.setChecked(ResearchStore.prefs(this).getBoolean("followQueries",true));box.addView(follow);TextView privacy=text("Se envía la pregunta al buscador y se visitan las fuentes. No se envían el historial, recuerdos ni proyectos. La biblioteca web guarda fragmentos con fecha y origen; no reentrena el modelo. Para seguir un tema: aprende sobre …",12);privacy.setTextColor(Color.BLACK);box.addView(privacy);ScrollView pane=new ScrollView(this);pane.addView(box);UiTypeface.show(new AlertDialog.Builder(this).setTitle("Internet y aprendizaje").setView(pane).setPositiveButton("Guardar",(d,w)->{ResearchStore.prefs(this).edit().putBoolean("enabled",enabled.isChecked()).putBoolean("wifi",wifi.isChecked()).putBoolean("followQueries",follow.isChecked()).apply();ResearchScheduler.configure(this);}).setNeutralButton("Ver biblioteca",(d,w)->command("biblioteca web")).setNegativeButton("Cerrar",null));}
 private void options(){LinearLayout box=new LinearLayout(this);box.setPadding(dp(16),dp(8),dp(16),dp(8));box.setOrientation(1);CheckBox experimental=new CheckBox(this);experimental.setText("Conversación experimental propia");experimental.setChecked(getSharedPreferences("banana-chat",0).getBoolean("transformer",true));box.addView(experimental);CheckBox three=new CheckBox(this);three.setText("Tres tomas en vista previa y guardado");three.setChecked(getSharedPreferences("cinema",0).getBoolean("three",false));box.addView(three);TextView info=new TextView(this);info.setText("Motores internos: Chat 3.4 + núcleo móvil 1 · Pixel 2.3. Voz sintética propia experimental. Modelos propios y procesamiento local. Las preguntas pueden consultar la web con fuentes. Aprendizaje: biblioteca actualizable, no entrenamiento automático.");box.addView(info);UiTypeface.show(new AlertDialog.Builder(this).setTitle("Opciones de Banana").setView(box).setPositiveButton("Guardar",(d,w)->{getSharedPreferences("banana-chat",0).edit().putBoolean("transformer",experimental.isChecked()).apply();getSharedPreferences("cinema",0).edit().putBoolean("three",three.isChecked()).apply();showHistory(false);}).setNegativeButton("Cancelar",null));}
 private void clear(){UiTypeface.show(new AlertDialog.Builder(this).setTitle("¿Borrar conversación?").setMessage("Borra los mensajes. Tu proyecto, borrador, personajes, recuerdos y escenas guardadas se conservan.").setPositiveButton("Borrar",(d,w)->{try{history=new JSONArray();topic="";DialogueMemory.resetConversation(this);MobileCore.resetConversation(this);record("Banana","Conversación nueva. Tu proyecto se conserva.",BananaProject.current(this),BananaProject.isDraft(this),true);}catch(Exception e){failed(e.getMessage());}}).setNegativeButton("Cancelar",null));}
 @Override public void edited(String message,String actor){try{record("Banana",message,BananaProject.current(this),BananaProject.isDraft(this),true);if(actor!=null&&!actor.isEmpty()&&active!=null)active.edit(actor);status.setText(message);}catch(Exception e){failed(e.getMessage());}}
 @Override public void restore(SceneDraft snapshot){if(locked())return;try{BananaProject.restore(this,snapshot);edited("Retomé esta versión del resultado.","");}catch(Exception e){failed(e.getMessage());}}
 @Override public void timeline(SceneDraft snapshot){try{if(!BananaProject.same(snapshot,BananaProject.current(this))){failed("Retomá esta versión antes de editar su secuencia.");return;}CreationPanels.timeline(this,()->edited("Actualicé la secuencia.",""));}catch(Exception e){failed(e.getMessage());}}
 @Override public void environment(SceneDraft snapshot){if(locked())return;try{if(!BananaProject.same(snapshot,BananaProject.current(this)))throw new IOException("Retomá esta versión antes de cambiar el ambiente.");UiTypeface.show(new AlertDialog.Builder(this).setTitle("Ambiente del resultado").setItems(new String[]{"Luz de día","Luz de noche","Luz cálida","Sin niebla","Poca niebla","Mucha niebla","Agregar árbol","Quitar árbol"},(d,i2)->command(new String[]{"pone el fondo de dia","pone el fondo de noche","luz calida","sin niebla","poca niebla","mucha niebla","agrega un arbol al fondo","quita el arbol del fondo"}[i2])).setNegativeButton("Cerrar",null));}catch(Exception e){failed(e.getMessage());}}
 @Override public void research(SceneDraft snapshot){if(locked())return;if(active!=null)active.stop();lock(true);status.setText("Consultando referencias del resultado…");worker=new Thread(()->{try{String response=BananaReferences.fetch(getApplicationContext(),snapshot);if(!dead)runOnUiThread(()->{lock(false);record("Banana",response,null,false,true);status.setText("Referencias consultadas; el proyecto se conserva.");});}catch(Throwable e){if(!dead)runOnUiThread(()->{lock(false);failed(e.getMessage());});}},"banana-result-references");worker.start();}
 @Override public void importReference(SceneDraft expected,String actor,boolean remove){if(locked())return;try{if(expected.get(actor)==null)throw new IOException("Elegí un personaje.");importRequest=new JSONObject().put("scene",expected.json()).put("actor",actor).put("remove",remove);Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.addCategory(Intent.CATEGORY_OPENABLE);pick.setType("image/*");startActivityForResult(pick,10);}catch(Exception e){failed(e.getMessage());}}
 @Override public void export(String kind,SceneDraft snapshot){if(locked())return;try{if(active!=null)active.stop();exportRequest=BananaExporter.request(this,kind,snapshot);if(kind.equals("png")&&active!=null&&BananaProject.same(snapshot,active.snapshot))exportRequest.put("time",active.stillTime());String ext=kind.equals("series")?"mp4":kind;Intent pick=new Intent(Intent.ACTION_CREATE_DOCUMENT);pick.addCategory(Intent.CATEGORY_OPENABLE);pick.setType(ext.equals("mp4")?"video/mp4":ext.equals("gif")?"image/gif":"image/png");pick.putExtra(Intent.EXTRA_TITLE,"Banana-"+System.currentTimeMillis()+"."+ext);startActivityForResult(pick,20);}catch(Exception e){failed(e.getMessage());}}
 private void knowledgeAction(String mode){Intent intent=new Intent(mode.equals("knowledge_export")?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType(mode.equals("knowledge_import_text")?"text/*":"application/zip");if(mode.equals("knowledge_import_text"))intent.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"text/plain","text/markdown"});if(mode.equals("knowledge_export"))intent.putExtra(Intent.EXTRA_TITLE,"Banana-conocimiento.zip");startActivityForResult(intent,mode.equals("knowledge_import_text")?64:mode.equals("knowledge_export")?65:66);}
 private void knowledgeFile(final int request,final Uri uri){lock(true);status.setText("Procesando documentos por fragmentos…");worker=new Thread(new Runnable(){public void run(){try{String answer;if(request==64){String title="Documento de texto";try(android.database.Cursor cursor=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())title=cursor.getString(0);}catch(Exception ignored){}if(title==null)title="Documento de texto";title=title.substring(0,Math.min(160,title.length()));try(InputStream in=getContentResolver().openInputStream(uri)){answer=KnowledgeNotebook.rememberReader(getApplicationContext(),title,NotebookDisk.reader(in),"archivo: "+title,"user");}}else if(request==66){try(InputStream in=getContentResolver().openInputStream(uri)){answer=NotebookArchive.restore(getApplicationContext(),in,false);}}else{File file=new File(getSharedPreferences("banana-notebook-files",0).getString("export",""));if(!file.getCanonicalPath().startsWith(getDir("apk-build",0).getCanonicalPath()+File.separator)||!file.isFile())throw new IOException("No encontré el respaldo preparado; pedime respaldar el conocimiento otra vez");try(InputStream in=new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(uri,"w")){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}answer="Guardé el respaldo completo de conocimiento.";}final String result=answer;if(!dead)runOnUiThread(new Runnable(){public void run(){lock(false);record("Banana",result,null,false,true);status.setText("Listo");}});}catch(Throwable e){if(!dead)runOnUiThread(new Runnable(){public void run(){lock(false);failed(AndroidRepair.summary(e));}});}}},"banana-knowledge-files");worker.start();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request>=64&&request<=66){knowledgeFile(request,uri);return;}if(request>=40&&request<=42){final String path=codeExportPath;lock(true);status.setText("Procesando código y firma…");worker=new Thread(()->{try{String text;if(request==40)text=ApkSigning.importKey(this,getContentResolver().openInputStream(uri));else if(request==42){JSONObject backup;try(InputStream in=getContentResolver().openInputStream(uri)){backup=new JSONObject(new String(OnDeviceJava.bytes(in,DurableCode.PORTABLE_LIMIT),"UTF-8"));}text=DurableCode.importBackup(this,backup);}else{File file=new File(path);if(!file.getCanonicalPath().startsWith(getDir("apk-build",0).getCanonicalPath()+File.separator)||!file.isFile())throw new IOException("Exportación no disponible; preparala otra vez.");try(InputStream in=new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(uri,"w")){byte[] bytes=new byte[65536];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);}text="Archivo guardado. Si es la APK, abrila para confirmar la actualización de Android.";}final String answer=text;if(!dead)runOnUiThread(()->{lock(false);record("Banana",answer,null,false,true);status.setText("Listo");});}catch(Throwable e){if(!dead)runOnUiThread(()->{lock(false);failed(AndroidRepair.summary(e));});}},"banana-code-files");worker.start();return;}if(request==10&&importRequest!=null){JSONObject q=importRequest;importRequest=null;lock(true);status.setText("Importando referencia…");worker=new Thread(()->{try{SceneDraft expected=SceneDraft.read(q.getJSONObject("scene").toString()),next=expected.copy();String id=q.getString("actor"),key="ref_"+UUID.randomUUID().toString().replace("-","");Bitmap bitmap=ReferenceImage.importBitmap(getApplicationContext(),uri,q.optBoolean("remove"));try(FileOutputStream out=openFileOutput(key+".png",0)){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();next.get(id).reference=key;next.focused=id;BananaProject.edit(getApplicationContext(),expected,next);if(!dead)runOnUiThread(()->{lock(false);edited("Importé la referencia de "+next.get(id).display()+".",id);});}catch(Throwable e){if(!dead)runOnUiThread(()->{lock(false);failed("No se importó: "+e.getMessage());});}},"banana-reference-import");worker.start();}
  if(request==20&&exportRequest!=null){JSONObject q=exportRequest;exportRequest=null;exporting=true;cancelExport=false;lock(true);status.setText("Guardando resultado…");worker=new Thread(()->{String message="Resultado guardado.";try{BananaExporter.write(getApplicationContext(),q,uri,new VideoExporter.Monitor(){public boolean cancelled(){return cancelExport||dead||Thread.currentThread().isInterrupted();}public void progress(int frame,int total){if(frame%12==0&&!dead)runOnUiThread(()->status.setText("Guardando: "+frame+"/"+total));}});}catch(Exception|OutOfMemoryError e){message="No se guardó: "+e.getMessage();}final String resultText=message;if(!dead)runOnUiThread(()->{exporting=false;lock(false);status.setText(resultText);});},"banana-result-export");worker.start();}}
 @Override public void failed(String message){if(status!=null)status.setText(message==null?"No se pudo completar la acción.":message);}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(intent.getBooleanExtra("open_editor",false)){showHistory(false);if(active!=null)active.edit(intent.getStringExtra("actor"));}}
 @Override protected void onResume(){super.onResume();resumed=true;if(active!=null)active.setForeground(true);}
 @Override protected void onPause(){resumed=false;super.onPause();if(active!=null)active.setForeground(false);}
 @Override protected void onDestroy(){dead=true;cancelExport=true;LearningLoop.setBusy(false);if(active!=null)active.close();if(worker!=null)worker.interrupt();super.onDestroy();}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);if(input!=null)b.putString("draft",input.getText().toString());if(exportRequest!=null)b.putString("export",exportRequest.toString());if(importRequest!=null)b.putString("import",importRequest.toString());}
}
